#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps GC from collecting it (crash in packaged build).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UArenaScoreTracker* without UPROPERTY, so the garbage collector (which runs periodically, ~60s in packaged builds) freed it; OnGoalScored then called AddPoints on a dangling pointer (EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints). Fixed by UPROPERTY() TObjectPtr.",
  "no_colors_cause": "DA_Primary palette is only referenced by string path in LoadObject, so the cooker never included /Game/Data/Palettes (bCookAll=False, only Arena map and Data/Effects cooked); packaged run logs 'Couldn't find file for package /Game/Data/Palettes/DA_Primary' and falls back to gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
